solution.solution.cpp:
#include <algorithm>
#include <cmath>
#include <limits>
#include <vector>

struct Vector3 { float x, y, z; };
struct Ray { Vector3 position, direction; };
struct BoundingBox { Vector3 min, max; };
struct Hit { bool hit{ false }; float distance{ 0 }; Vector3 point{ 0, 0, 0 }, normal{ 0, 0, 0 }; };

namespace
{
    Vector3 along(Ray r, float t) { return { r.position.x + r.direction.x * t, r.position.y + r.direction.y * t, r.position.z + r.direction.z * t }; }
    float get(Vector3 v, int a) { return a == 0 ? v.x : a == 1 ? v.y : v.z; }
}

Hit rayPlaneY(Ray r, float height)
{
    Hit h;
    if (r.direction.y == 0) return h;
    const float t{ (height - r.position.y) / r.direction.y };
    if (t < 0) return h;
    h.hit = true;
    h.distance = t;
    h.point = along(r, t);
    h.normal = { 0, r.position.y >= height ? 1.0f : -1.0f, 0 };
    return h;
}

Hit raySphere(Ray r, Vector3 centre, float radius)
{
    Hit h;
    const Vector3 m{ r.position.x - centre.x, r.position.y - centre.y, r.position.z - centre.z };
    const float b{ m.x * r.direction.x + m.y * r.direction.y + m.z * r.direction.z };
    const float c{ m.x * m.x + m.y * m.y + m.z * m.z - radius * radius };
    if (c > 0 && b > 0) return h;
    const float disc{ b * b - c };
    if (disc < 0) return h;
    float t{ -b - std::sqrt(disc) };
    h.hit = true;
    if (t < 0) { h.distance = 0; h.point = r.position; return h; }
    h.distance = t;
    h.point = along(r, t);
    h.normal = { (h.point.x - centre.x) / radius, (h.point.y - centre.y) / radius, (h.point.z - centre.z) / radius };
    return h;
}

Hit rayBox(Ray r, BoundingBox b)
{
    Hit h;
    float tmin{ 0 }, tmax{ std::numeric_limits<float>::infinity() };
    int axis{ -1 };
    for (int a{ 0 }; a < 3; ++a)
    {
        const float p{ get(r.position, a) }, d{ get(r.direction, a) }, lo{ get(b.min, a) }, hi{ get(b.max, a) };
        if (d == 0)
        {
            if (p < lo || p > hi) return h;
            continue;
        }
        float t1{ (lo - p) / d }, t2{ (hi - p) / d };
        if (t1 > t2) std::swap(t1, t2);
        if (t1 > tmin) { tmin = t1; axis = a; }
        tmax = std::min(tmax, t2);
        if (tmin > tmax) return h;
    }
    h.hit = true;
    h.distance = tmin;
    h.point = along(r, tmin);
    if (axis >= 0)
    {
        const float s{ get(r.direction, axis) > 0 ? -1.0f : 1.0f };
        h.normal = { axis == 0 ? s : 0.0f, axis == 1 ? s : 0.0f, axis == 2 ? s : 0.0f };
    }
    return h;
}

int pickNearest(Ray r, const std::vector<BoundingBox>& boxes)
{
    int best{ -1 };
    float bestDist{ std::numeric_limits<float>::infinity() };
    for (std::size_t i{ 0 }; i < boxes.size(); ++i)
    {
        const Hit h{ rayBox(r, boxes[i]) };
        if (h.hit && h.distance < bestDist) { bestDist = h.distance; best = static_cast<int>(i); }
    }
    return best;
}

unitTests:
bool near3(Vector3 v, float x, float y, float z) { return std::fabs(v.x - x) < 1e-4f && std::fabs(v.y - y) < 1e-4f && std::fabs(v.z - z) < 1e-4f; }
TEST("plane") {
    Hit h = rayPlaneY({ { 1, 10, 2 }, { 0, -1, 0 } }, 2); CHECK(h.hit); CHECK_NEAR(h.distance, 8.0, 1e-4); CHECK(near3(h.point, 1, 2, 2)); CHECK(near3(h.normal, 0, 1, 0));
    CHECK(!rayPlaneY({ { 0, 10, 0 }, { 1, 0, 0 } }, 2).hit); CHECK(!rayPlaneY({ { 0, 10, 0 }, { 0, 1, 0 } }, 2).hit);
    CHECK(near3(rayPlaneY({ { 0, -3, 0 }, { 0, 1, 0 } }, 2).normal, 0, -1, 0));
}
TEST("sphere") {
    Hit h = raySphere({ { 0, 0, -10 }, { 0, 0, 1 } }, { 0, 0, 0 }, 2); CHECK(h.hit); CHECK_NEAR(h.distance, 8.0, 1e-4); CHECK(near3(h.normal, 0, 0, -1));
    CHECK(raySphere({ { 0, 0, 0 }, { 1, 0, 0 } }, { 0, 0, 0 }, 2).hit); CHECK_NEAR(raySphere({ { 0, 0, 0 }, { 1, 0, 0 } }, { 0, 0, 0 }, 2).distance, 0.0, 1e-6);
    CHECK(!raySphere({ { 0, 3, -10 }, { 0, 0, 1 } }, { 0, 0, 0 }, 2).hit); CHECK(!raySphere({ { 0, 0, 10 }, { 0, 0, 1 } }, { 0, 0, 0 }, 2).hit);
}
TEST("box faces") {
    const BoundingBox b{ { -1, -1, -1 }, { 1, 1, 1 } };
    Hit h = rayBox({ { -5, 0, 0 }, { 1, 0, 0 } }, b); CHECK(h.hit); CHECK_NEAR(h.distance, 4.0, 1e-4); CHECK(near3(h.normal, -1, 0, 0));
    h = rayBox({ { 0, 5, 0 }, { 0, -1, 0 } }, b); CHECK_NEAR(h.distance, 4.0, 1e-4); CHECK(near3(h.normal, 0, 1, 0));
    h = rayBox({ { 0.5f, 0.2f, 9 }, { 0, 0, -1 } }, b); CHECK_NEAR(h.distance, 8.0, 1e-4); CHECK(near3(h.point, 0.5f, 0.2f, 1)); CHECK(near3(h.normal, 0, 0, 1));
}
TEST("box misses and inside") {
    const BoundingBox b{ { -1, -1, -1 }, { 1, 1, 1 } };
    CHECK(!rayBox({ { -5, 2, 0 }, { 1, 0, 0 } }, b).hit); CHECK(!rayBox({ { 5, 0, 0 }, { 1, 0, 0 } }, b).hit);
    CHECK(!rayBox({ { -5, -5, 0 }, { 0.70711f, 0.70711f, 0 } }, { { -1, 1.5f, -1 }, { 1, 2, 1 } }).hit);
    const Hit in = rayBox({ { 0, 0, 0 }, { 0, 0, 1 } }, b); CHECK(in.hit); CHECK_NEAR(in.distance, 0.0, 1e-6); CHECK(near3(in.normal, 0, 0, 0));
}
TEST("picking the nearest") {
    const std::vector<BoundingBox> boxes{ { { -1, -1, 9 }, { 1, 1, 10 } }, { { -1, -1, 4 }, { 1, 1, 5 } }, { { 5, -1, 1 }, { 6, 1, 2 } } };
    CHECK_EQ(pickNearest({ { 0, 0, 0 }, { 0, 0, 1 } }, boxes), 1); CHECK_EQ(pickNearest({ { 0, 0, 0 }, { 0, 0, -1 } }, boxes), -1);
    CHECK_EQ(pickNearest({ { 0, 0, 0 }, { 0.9701f, 0, 0.2425f } }, boxes), 2);
}

